<body>
<main class="wrap">
  <h1>Pocket Garden</h1>
  <p class="intro">Pick plants for your garden and mark the ones you've planted.</p>
  <p class="note">Your choices reset when you reload the page.</p>

  <fieldset class="filters" id="filters">
    <legend>Filter plants</legend>
    <button type="button" data-filter="all" aria-pressed="true">All plants</button>
    <button type="button" data-filter="sun" aria-pressed="false">Loves sun</button>
    <button type="button" data-filter="shade" aria-pressed="false">Likes shade</button>
  </fieldset>

  <p class="status" id="status" role="status" aria-live="polite"></p>

  <section class="grid" aria-label="Plants">
    <article class="card" data-light="sun">
      <span class="emoji" aria-hidden="true">🌿</span>
      <h2>Basil</h2>
      <span class="tag sun">Loves sun</span>
      <p>A fragrant herb that thrives in warm, bright spots.</p>
      <button type="button" class="plant-btn" aria-pressed="false" data-name="Basil">Mark as planted</button>
    </article>

    <article class="card" data-light="sun">
      <span class="emoji" aria-hidden="true">🌻</span>
      <h2>Sunflower</h2>
      <span class="tag sun">Loves sun</span>
      <p>A tall, cheerful bloom that follows full sunlight.</p>
      <button type="button" class="plant-btn" aria-pressed="false" data-name="Sunflower">Mark as planted</button>
    </article>

    <article class="card" data-light="shade">
      <span class="emoji" aria-hidden="true">🍃</span>
      <h2>Mint</h2>
      <span class="tag shade">Likes shade</span>
      <p>A hardy, refreshing herb that is happy in cooler, shadier corners.</p>
      <button type="button" class="plant-btn" aria-pressed="false" data-name="Mint">Mark as planted</button>
    </article>
  </section>
</main>

<script>
  (function () {
    var filterButtons = document.querySelectorAll("#filters button");
    var cards = document.querySelectorAll(".card");
    var status = document.getElementById("status");
    var filterNames = { all: "All plants", sun: "Loves sun", shade: "Likes shade" };

    function applyFilter(filter) {
      var shown = 0;
      cards.forEach(function (card) {
        var match = filter === "all" || card.dataset.light === filter;
        card.hidden = !match;
        if (match) shown++;
      });
      filterButtons.forEach(function (b) {
        b.setAttribute("aria-pressed", String(b.dataset.filter === filter));
      });
      status.textContent = "Showing " + shown + " of " + cards.length +
        " plants (" + filterNames[filter] + ").";
    }

    filterButtons.forEach(function (b) {
      b.addEventListener("click", function () { applyFilter(b.dataset.filter); });
    });

    document.querySelectorAll(".plant-btn").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var planted = btn.getAttribute("aria-pressed") !== "true";
        btn.setAttribute("aria-pressed", String(planted));
        btn.textContent = planted ? "Planted" : "Mark as planted";
        btn.closest(".card").classList.toggle("planted", planted);
      });
    });

    applyFilter("all");
  })();
</script>
</body>
